/*
 * A aba "Lidos" do perfil: os tópicos que a pessoa leu, do mais recente para
 * o mais antigo (`filter[canelaReadBy]`, de extend/activity.php), na lista de
 * tópicos de sempre. Só a própria pessoa e administradores a veem; o
 * servidor confere de novo.
 */
import UserPage from 'flarum/forum/components/UserPage';
import DiscussionList from 'flarum/forum/components/DiscussionList';
import DiscussionListState from 'flarum/forum/states/DiscussionListState';
import { leaveIfHidden } from './install';
export default class ReadUserPage extends UserPage {
  oninit(vnode) {
    super.oninit(vnode);
    this.loadUser(m.route.param('username'));
  }
  show(user) {
    if (leaveIfHidden('read', user)) return;
    super.show(user);
    this.state = new DiscussionListState({
      filter: {
        canelaReadBy: user.slug()
      }
    });
    this.state.refresh();
  }
  content() {
    return m("div", {
      className: "DiscussionsUserPage CanelaReadUserPage"
    }, this.state && m(DiscussionList, {
      state: this.state
    }));
  }
}
flarum.reg.add('ramon-canela', 'forum/user/activity/ReadUserPage', ReadUserPage);